package topicshadow

import (
	"context"
	"fmt"
	"strings"
)

type JevCandidate struct {
	Card  TopicCard
	Facts []string
}

// ClassifyJev performs one combined topic and relation judgment. All evidence
// is selected from bounded source excerpts, never generated by the model.
func ClassifyJev(ctx context.Context, client DecisionsTransport, article ArticleInput, candidates []JevCandidate) (MatchResult, NoveltyResult, error) {
	if client == nil {
		return MatchResult{}, NoveltyResult{}, &DecisionsError{Code: "configuration"}
	}
	cards := make([]TopicCard, 0, len(candidates))
	total := 0
	for _, c := range candidates {
		cards = append(cards, c.Card)
		if len(c.Facts) > maxFacts {
			return MatchResult{}, NoveltyResult{}, &DecisionsError{Code: "invalid_request"}
		}
		for _, f := range c.Facts {
			total += len(f)
			if strings.TrimSpace(f) == "" || len(f) > maxFactBytes || total > 12<<10 {
				return MatchResult{}, NoveltyResult{}, &DecisionsError{Code: "invalid_request"}
			}
		}
	}
	_, err := validateMatchInput(article, cards)
	if err != nil {
		return MatchResult{}, NoveltyResult{}, err
	}
	// Evidence is restricted to summaries rather than the headline.
	excerpts := makeExcerpts(ArticleInput{Summary: article.Summary, SerbianSummary: article.SerbianSummary})
	if len(excerpts) == 0 {
		return MatchResult{}, NoveltyResult{}, &DecisionsError{Code: "invalid_request"}
	}
	input := formatMatch(article, excerpts, cards)
	for _, c := range candidates {
		for _, f := range c.Facts {
			input += fmt.Sprintf("Known fact for %s: %s\n", c.Card.ID, f)
		}
	}
	decision := matchDecisionQuestion(cards)
	decision.Instructions = "Decide story identity, independently of novelty or authority. Choose the existing candidate when the incoming text describes the same specific event, legal process, launch, or documented direct consequence. A tentative date and its later official confirmation can be the same story. Choose new_candidate when the definite subject is distinct from all candidates, including a first official decision. Choose review only if identity is ambiguous."
	for i := range decision.Choices {
		if decision.Choices[i].Value == MatchOutcomeNewCandidate {
			decision.Choices[i].Description = "A definite separate subject, including an official first event or an article that may be the start of a story."
		}
	}
	relation := ChoiceQuestion{Name: "relation", Instructions: "For the same specific story compare the incoming summary with the card and its known facts. A confirmed scheduled date replacing a merely tentative date is material_update. A new publication with the same confirmed date, including extra details or a different source, is repeat. Select context for background or commentary, review for rumor or insufficient evidence. When no card fits, choose material_update for an explicit formal decision, actual action or reported concrete result in the first article.", Choices: []ChoiceOption{{Value: NoveltyOutcomeMaterialUpdate, Description: "Confirmed significant new development."}, {Value: NoveltyOutcomeRepeat, Description: "Already known fact."}, {Value: NoveltyOutcomeContext, Description: "Background or commentary."}, {Value: NoveltyOutcomeReview, Description: "Rumor, ambiguity or insufficient evidence."}}}
	official := ChoiceQuestion{Name: "official_change", Instructions: "Is a concrete official decision, action or result explicitly established in the selected summary excerpt? Proposals, plans, rumors and allegations are no.", Choices: []ChoiceOption{{Value: "yes", Description: "Explicitly established official change."}, {Value: "no", Description: "No established official change."}}}
	evidence := matchEvidenceQuestion(excerpts)
	evidence.Instructions = "Select the summary excerpt that directly establishes the concrete topic and reported development. Choose review if none does."
	qs := []ChoiceQuestion{decision, relation, official, evidence}
	result, err := client.Decide(ctx, input, qs)
	if err != nil {
		return MatchResult{}, NoveltyResult{}, err
	}
	m := MatchResult{Outcome: MatchOutcomeReview, Usage: result.Usage, Model: result.Model, ProbabilityJudgments: map[string][]ChoiceProbability{}}
	n := NoveltyResult{Outcome: NoveltyOutcomeReview, Usage: result.Usage, Model: result.Model, ProbabilityJudgments: map[string][]ChoiceProbability{}}
	if result.Refusal != "" {
		return m, n, nil
	}
	answers := map[string]ChoiceAnswer{}
	for _, q := range qs {
		a, ok := answerByName(result, q.Name)
		if !ok {
			return m, n, &DecisionsError{Code: "invalid_response"}
		}
		valid := false
		for _, ch := range q.Choices {
			if a.Choice == ch.Value {
				valid = true
			}
		}
		if !valid {
			return m, n, &DecisionsError{Code: "invalid_response"}
		}
		answers[q.Name] = a
		m.ProbabilityJudgments[q.Name] = a.Probabilities
		n.ProbabilityJudgments[q.Name] = a.Probabilities
	}
	d, r, o, e := answers["decision"], answers["relation"], answers["official_change"], answers["evidence"]
	m.Confidence = answerConfidence(d)
	m.Margin = choiceMargin(d)
	m.Probabilities = d.Probabilities
	n.Confidence = answerConfidence(r)
	n.Margin = choiceMargin(r)
	n.Probabilities = r.Probabilities
	ex, ok := excerptByID(excerpts, e.Choice)
	if !ok {
		if e.Choice == "review" {
			return m, n, nil
		}
		return m, n, &DecisionsError{Code: "invalid_response"}
	}
	m.EvidenceExcerptID = ex.id
	m.EvidenceSpan = ex.text
	n.EvidenceExcerptID = ex.id
	n.EvidenceSpan = ex.text
	if answerConfidence(e) < otherConfidenceThreshold || hasAmbiguousReferent(articleText(article)) {
		return m, n, nil
	}
	if strings.HasPrefix(d.Choice, topicChoicePrefix) && m.Confidence >= matchConfidenceThreshold && m.Margin >= 0.5 {
		for _, card := range cards {
			if d.Choice == topicChoicePrefix+card.ID {
				m.Outcome = MatchOutcomeMatch
				m.TopicID = card.ID
			}
		}
	}
	uncertain := jevUncertain(ex.text) || jevUncertain(article.Title)
	concrete := o.Choice == "yes" && answerConfidence(o) >= matchConfidenceThreshold && choiceMargin(o) >= otherConfidenceThreshold && !uncertain
	n.ConcreteStatusChange = concrete
	if d.Choice == MatchOutcomeNewCandidate && m.Confidence >= matchConfidenceThreshold && m.Margin >= 0.5 && !uncertain {
		m.Outcome = MatchOutcomeNewCandidate
		n.SubjectCandidate = true
	}
	if m.Outcome == MatchOutcomeReview {
		return m, n, nil
	}
	if m.Outcome == MatchOutcomeNewCandidate && concrete && r.Choice == NoveltyOutcomeMaterialUpdate {
		n.Confidence, n.Margin = answerConfidence(o), choiceMargin(o)
		n.Outcome = NoveltyOutcomeMaterialUpdate
		return m, n, nil
	}
	if m.Outcome == MatchOutcomeMatch {
		for _, candidate := range candidates {
			if candidate.Card.ID != m.TopicID {
				continue
			}
			fingerprint := normalizedPhrase(ex.text)
			for _, fact := range candidate.Facts {
				if fingerprint != "" && normalizedPhrase(fact) == fingerprint {
					n.Outcome = NoveltyOutcomeRepeat
					return m, n, nil
				}
			}
		}
	}
	switch r.Choice {
	case NoveltyOutcomeMaterialUpdate:
		if n.Confidence >= matchConfidenceThreshold && n.Margin >= 0.5 && !uncertain && (m.Outcome != MatchOutcomeNewCandidate || concrete) {
			n.Outcome = r.Choice
		}
	case NoveltyOutcomeContext, NoveltyOutcomeRepeat:
		if n.Confidence >= otherConfidenceThreshold {
			n.Outcome = r.Choice
		}
	}
	return m, n, nil
}
func jevUncertain(s string) bool {
	s = strings.ToLower(s)
	for _, marker := range []string{"rumor", "rumour", "alleged", "reportedly", "unconfirmed", "may ", "could ", "planned", "proposed", "слух", "якобы", "предполож", "возможно", "планирует", "предлагает", "navodno", "nezvanično", "planira"} {
		if strings.Contains(s, marker) {
			return true
		}
	}
	return false
}
